setup.body:
config <- either throw pure (Native.decodeConfig (Contract.input (Contract.encodeInput args)))
result <- Native.setupWith config
pure { tool: result.tool, version: result.version, binDir: result.binDir, environment: Contract.variables result.environment, sdkRoot: result.sdkRoot, javaVersion: result.javaVersion, commandLineToolsBuild: result.commandLineToolsBuild }
